#include <stdio.h>
#include <string.h>
#include <stdlib.h>

static int matches(char open, char close) {
    return (open == '(' && close == ')') ||
           (open == '[' && close == ']') ||
           (open == '{' && close == '}');
}

static int is_balanced(const char *s) {
    size_t len = strlen(s);
    char *stack = (char *)malloc(len);
    size_t top = 0;
    for (size_t i = 0; i < len; ++i) {
        char c = s[i];
        if (c == '(' || c == '[' || c == '{') {
            stack[top++] = c;
        } else if (c == ')' || c == ']' || c == '}') {
            if (top == 0) { free(stack); return 0; }
            if (!matches(stack[--top], c)) { free(stack); return 0; }
        } else {
            free(stack);
            return 0;
        }
    }
    int ok = (top == 0);
    free(stack);
    return ok;
}

int main(int argc, char *argv[]) {
    const char *input = (argc >= 2) ? argv[1] : "";
    puts(is_balanced(input) ? "BALANCED" : "UNBALANCED");
    return 0;
}
